import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { test } from 'node:test';
import { DatabaseSync } from 'node:sqlite';

async function startServer(databasePath) {
  const child = spawn(process.execPath, ['server.js'], {
    env: { ...process.env, PORT: '0', DB_PATH: databasePath },
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  let stderr = '';
  child.stderr.on('data', (chunk) => { stderr += chunk; });
  const baseUrl = await new Promise((resolve, reject) => {
    let output = '';
    child.stdout.on('data', (chunk) => {
      output += chunk;
      const match = output.match(/listening on port (\d+)/);
      if (match) resolve(`http://127.0.0.1:${match[1]}`);
    });
    child.once('error', reject);
    child.once('exit', (code) => reject(new Error(`Server exited (${code}): ${stderr}`)));
  });
  return {
    baseUrl,
    async stop() {
      const exited = once(child, 'exit');
      child.kill('SIGTERM');
      await exited;
    },
  };
}

async function create(baseUrl, name) {
  return fetch(`${baseUrl}/projects`, {
    method: 'POST',
    body: new URLSearchParams({ name }),
    redirect: 'manual',
  });
}

async function post(baseUrl, path, fields) {
  return fetch(`${baseUrl}${path}`, {
    method: 'POST', body: new URLSearchParams(fields), redirect: 'manual',
  });
}

function taskRows(html) {
  return [...html.matchAll(/<li data-testid="task-row">([\s\S]*?)<\/li>/g)].map((match) => ({
    title: match[1].match(/<span>(.*?)<\/span>/s)[1],
    path: match[1].match(/action="(.*?)"/)[1],
    completed: / checked/.test(match[1]),
  }));
}

function projectSummaries(html) {
  return [...html.matchAll(/data-testid="project-summary">(.*?)<\/span>/g)].map((match) => match[1]);
}

function projectRows(html) {
  return [...html.matchAll(/<li data-testid="project-row">([\s\S]*?)<\/li>/g)].map((match) => ({
    name: match[1].match(/<span>(.*?)<\/span>/s)[1],
    path: match[1].match(/action="(.*?)"/)[1],
  }));
}

function priorityControls(html) {
  return [...html.matchAll(/<select id="task-priority-\d+"[^>]*>([\s\S]*?)<\/select>/g)].map((match) => ({
    disabled: / disabled/.test(match[0]),
    options: [...match[1].matchAll(/<option(?: selected)?>(.*?)<\/option>/g)].map((option) => option[1]),
    selected: match[1].match(/<option selected>(.*?)<\/option>/)[1],
  }));
}

function directoryRows(html) {
  return [...html.matchAll(/<li data-testid="directory-task-row">([\s\S]*?)<\/li>/g)].map((match) => {
    const field = (name) => match[1].match(new RegExp(`data-testid="directory-${name}"[^>]*>([\\s\\S]*?)<\\/span>`))[1];
    return { title: field('task-title'), project: field('project-name'),
      completion: field('task-completion'), priority: field('task-priority'),
      date: field('task-due-date'), notes: field('task-notes'), html: match[1] };
  });
}

test('directory order spans owners, retains filters and bulk actions, and never changes stored order', { timeout: 15000 }, async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-directory-order-'));
  const databasePath = join(directory, 'board.sqlite');
  let server;
  try {
    server = await startServer(databasePath);
    const task = (title, priority, dueDate, deleted = false) => ({ title, priority, dueDate,
      deleted, completed: false, notes: 'unchanged' });
    const imported = async (name, archived, tasks) => {
      const response = await post(server.baseUrl, '/projects/import', { name,
        json: JSON.stringify({ format: 'workboard-project', version: 1,
          project: { name, archived, defaultPriority: 'Normal', tasks } }) });
      return response.headers.get('location');
    };
    const first = await imported('First', false, [task('Zulu', 'Low', ''),
      task('beta', 'High', '2025-01-02'), task('Deleted Z', 'Low', '', true),
      task('Deleted A', 'High', '2024-01-01', true)]);
    const second = await imported('Second', false, [task('Alpha', 'Normal', '2024-01-01'),
      task('BETA', 'High', '2025-01-02')]);
    await imported('Archived', true, [task('Zulu archived', 'Low', ''),
      task('Alpha archived', 'High', '2024-01-01')]);
    const snapshot = async (path) => (await fetch(`${server.baseUrl}${path}/download`)).json();
    const before = [await snapshot(first), await snapshot(second)];
    const view = async (query = '') => (await fetch(`${server.baseUrl}/directory${query ? `?${query}` : ''}`)).text();
    const titles = (html) => directoryRows(html).map((row) => row.title);
    const initial = await view();
    assert.match(initial, /<option selected>Original<\/option>/);
    assert.deepEqual(titles(initial), ['Zulu', 'beta', 'Alpha', 'BETA']);
    for (const [order, expected] of [
      ['Priority', ['beta', 'BETA', 'Alpha', 'Zulu']],
      ['Due date', ['Alpha', 'beta', 'BETA', 'Zulu']],
      ['Title', ['Alpha', 'beta', 'BETA', 'Zulu']],
    ]) {
      const html = await view(new URLSearchParams({ order }).toString());
      assert.deepEqual(titles(html), expected);
      assert.match(html, new RegExp(`<option selected>${order}<\\/option>`));
      assert.equal([...html.matchAll(new RegExp(`name="order" value="${order}"`, 'g'))].length, 3);
    }
    assert.deepEqual(titles(await view('scope=Archived&order=Title')), ['Alpha archived', 'Zulu archived']);
    assert.deepEqual(titles(await view('filter=Deleted&order=Priority')), ['Deleted A', 'Deleted Z']);
    const fields = { scope: 'Active', filter: 'Open', priorityFilter: 'High',
      dueFrom: '2025-01-01', dueThrough: '2025-12-31', search: 'beta', order: 'Title' };
    const filtered = await view(new URLSearchParams(fields).toString());
    assert.deepEqual(titles(filtered), ['beta', 'BETA']);
    const invalid = await view(new URLSearchParams({ ...fields, dueFrom: '2025-02-30',
      appliedFrom: fields.dueFrom, appliedThrough: fields.dueThrough }).toString());
    assert.deepEqual(titles(invalid), ['beta', 'BETA']);
    assert.match(invalid, /<option selected>Title<\/option>/);
    assert.deepEqual([await snapshot(first), await snapshot(second)], before);
    const response = await post(server.baseUrl, '/directory/completion', { ...fields, completed: '1' });
    const location = response.headers.get('location');
    const params = new URL(location, server.baseUrl).searchParams;
    for (const [key, value] of Object.entries(fields)) assert.equal(params.get(key), value);
    const empty = await (await fetch(`${server.baseUrl}${location}`)).text();
    assert.deepEqual(titles(empty), []);
    assert.match(empty, /No matching tasks/);
    assert.match(empty, /<option selected>Title<\/option>/);
    const after = [await snapshot(first), await snapshot(second)];
    before[0].project.tasks[1].completed = true;
    before[1].project.tasks[1].completed = true;
    assert.deepEqual(after, before);
    assert.deepEqual(taskRows(await (await fetch(`${server.baseUrl}${first}`)).text()).map((row) => row.title), ['Zulu', 'beta']);
    await server.stop();
    server = await startServer(databasePath);
    assert.deepEqual([await snapshot(first), await snapshot(second)], after);
    assert.deepEqual(titles(await view()), ['Zulu', 'beta', 'Alpha', 'BETA']);
    assert.match(await view(), /<option selected>Original<\/option>/);
  } finally {
    if (server) await server.stop();
    await rm(directory, { recursive: true, force: true });
  }
});

test('directory bulk completion changes only eligible matching tasks and persists', { timeout: 15000 }, async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-bulk-'));
  const databasePath = join(directory, 'board.sqlite');
  let server;
  try {
    server = await startServer(databasePath);
    const task = (title, fields = {}) => ({ title, completed: false, priority: 'High',
      dueDate: '2024-02-29', notes: '  literal <b>📝</b>\n  ', deleted: false, ...fields });
    const imported = async (name, archived, tasks) => post(server.baseUrl, '/projects/import', {
      name, json: JSON.stringify({ format: 'workboard-project', version: 1,
        project: { name, archived, defaultPriority: 'Low', tasks } }),
    });
    await imported('First', false, [task('Hit  One'), task('Hit Two', { completed: true }),
      task('Hit Deleted', { deleted: true }), task('Hit Low', { priority: 'Low' }),
      task('Hit Undated', { dueDate: '' }), task('Miss'), task('Hit Later', { dueDate: '2024-03-01' })]);
    await imported('Second', false, [task('HIT\tThree')]);
    await imported('Archived', true, [task('Hit Archived')]);
    const snapshot = () => {
      const db = new DatabaseSync(databasePath);
      try { return {
        tasks: db.prepare('SELECT * FROM tasks ORDER BY id').all().map((row) => ({ ...row })),
        projects: db.prepare('SELECT * FROM projects ORDER BY id').all(),
        positions: db.prepare('SELECT * FROM task_positions ORDER BY project_id, position').all(),
      }; } finally { db.close(); }
    };
    const before = snapshot();
    const fields = { scope: 'Active', filter: 'Open', priorityFilter: 'High',
      search: '  hit ', dueFrom: '2024-02-29', dueThrough: '2024-02-29' };
    const get = async (query = fields) => (await fetch(`${server.baseUrl}/directory?${new URLSearchParams(query)}`)).text();
    const enabled = (html, label) => !new RegExp(`<button[^>]*disabled[^>]*>${label}</button>`).test(html);
    let html = await get();
    assert.equal(enabled(html, 'Complete visible tasks'), true);
    assert.equal(enabled(html, 'Reopen visible tasks'), false);
    assert.deepEqual(directoryRows(html).map((row) => row.title), ['Hit  One', 'HIT\tThree']);
    const bulk = (query, completed) => post(server.baseUrl, '/directory/completion', { ...query, completed });
    let response = await bulk(fields, '1');
    assert.equal(response.status, 303);
    const location = response.headers.get('location');
    assert.equal(new URL(location, server.baseUrl).searchParams.get('search'), 'hit');
    html = await (await fetch(`${server.baseUrl}${location}`)).text();
    assert.deepEqual(directoryRows(html), []);
    assert.match(html, />No matching tasks<\/p>/);
    assert.equal(enabled(html, 'Complete visible tasks'), false);
    assert.equal(enabled(html, 'Reopen visible tasks'), false);
    const after = snapshot();
    assert.deepEqual(after.projects, before.projects);
    assert.deepEqual(after.positions, before.positions);
    assert.deepEqual(after.tasks, before.tasks.map((row) => ({ ...row,
      completed: [1, 8].includes(row.id) ? 1 : row.completed })));
    assert.deepEqual(projectSummaries(await (await fetch(server.baseUrl)).text()), ['2/6 completed', '1/1 completed']);

    for (const query of [{ ...fields, scope: 'Archived' }, { ...fields, filter: 'Deleted' },
      { ...fields, search: 'no match' }]) {
      html = await get(query);
      assert.equal(enabled(html, 'Complete visible tasks'), false);
      assert.equal(enabled(html, 'Reopen visible tasks'), false);
      await bulk(query, '0');
      assert.deepEqual(snapshot(), after);
    }
    response = await bulk({ ...fields, dueFrom: '1900-02-29' }, '0');
    assert.equal(response.status, 400);
    assert.deepEqual(snapshot(), after);
    response = await bulk(fields, 'bad');
    assert.equal(response.status, 400);
    assert.deepEqual(snapshot(), after);

    await server.stop();
    server = await startServer(databasePath);
    assert.deepEqual(snapshot(), after);
    const completedFields = { ...fields, filter: 'Completed' };
    html = await get(completedFields);
    assert.equal(enabled(html, 'Complete visible tasks'), false);
    assert.equal(enabled(html, 'Reopen visible tasks'), true);
    assert.equal(directoryRows(html).length, 3);
    response = await bulk(completedFields, '0');
    html = await (await fetch(`${server.baseUrl}${response.headers.get('location')}`)).text();
    assert.deepEqual(directoryRows(html), []);
    assert.match(html, /<option selected>Completed<\/option>/);
    const reopened = snapshot();
    assert.deepEqual(reopened.tasks, before.tasks.map((row) => ({ ...row,
      completed: [1, 2, 8].includes(row.id) ? 0 : row.completed })));
    await server.stop();
    server = await startServer(databasePath);
    assert.deepEqual(snapshot(), reopened);
    await post(server.baseUrl, '/projects/1/tasks/1/move', { destination: '2' });
    await post(server.baseUrl, '/projects/2/tasks/1/move', { destination: '1' });
    assert.deepEqual(snapshot().tasks, reopened.tasks);
    assert.deepEqual(directoryRows(await get({})).map((row) => row.title),
      ['Hit  One', 'Hit Two', 'Hit Low', 'Hit Undated', 'Miss', 'Hit Later', 'HIT\tThree']);
    const returned = snapshot();
    // All allows mixed completion states; repeated actions are idempotent.
    const all = { ...fields, filter: 'All' };
    await bulk(all, '1');
    const complete = snapshot();
    await bulk(all, '1');
    assert.deepEqual(snapshot(), complete);
    await bulk(all, '0');
    assert.deepEqual(snapshot(), returned);
  } finally {
    if (server) await server.stop();
    await rm(directory, { recursive: true, force: true });
